"""Keyframe images generated by the Codex CLI's built-in image tool (ChatGPT login, no API key needed).

Each image is one `codex exec` run in the output folder: the prompt (sent on stdin, because `-i` takes a list of
files) asks Codex to generate the picture with its image tool and save it under a given name. Reference images
(album cover, character sheet) are attached with `-i`. A shot that continues the previous one also gets the previous
keyframe attached, so it is drawn as the next moment of the same take; such jobs run after the one they continue.
"""

from __future__ import annotations

import dataclasses
import subprocess
import threading
import time
from dataclasses import dataclass, field
from pathlib import Path

from PIL import Image

SIZES = {"landscape": "1536x1024", "portrait": "1024x1536"}


@dataclass
class ImageJob:
    out: Path
    prompt: str
    orientation: str  # landscape | portrait
    refs: list[Path] = field(default_factory=list)
    previous: Path | None = None  # keyframe of the shot this one continues (attached once it exists)
    anchor: Path | None = None  # first keyframe of the same location earlier in the video (after a cut)
    fingerprint: str = ""  # what the image is drawn from; saved next to it so later edits can mark it stale
    fix_note: Path | None = None  # correction from the keyframe check, removed once the image is redrawn
    replace: bool = False  # an existing (stale) image is redrawn; it is kept until the new one succeeds

    def attachments(self) -> list[Path]:
        extra = [x for x in (self.previous, self.anchor) if x and x.exists()]
        return [*self.refs, *dict.fromkeys(extra)]

    def depends_on(self) -> list[Path]:
        return [x for x in (self.previous, self.anchor) if x]


SIDES = ("Left and right: 'on the left/right of the frame' means the picture; a person's or vehicle's own left/right "
         "turns with the camera - seen from the front their own left is on the RIGHT of the picture, seen from behind "
         "on the left. Do not mirror the scene.")


def _instruction(job: ImageJob) -> str:
    refs, files = "", job.attachments()
    if files:
        names = ", ".join(f"attached image {i + 1} ({p.stem.replace('_', ' ')})" for i, p in enumerate(files))
        refs = (f"Reference images: {names}. Match the palette, mood and paper-craft style of the references, and if a "
                "character sheet is attached the woman must look exactly like the woman on it. ")
    if job.previous in files:
        refs += (f"Attached image {len(files)} is the PREVIOUS MOMENT of this same continuous camera take: keep the "
                 "same place, set pieces, lighting, palette, weather and character (same clothes, same hair), built "
                 "from the same paper pieces; change only what the scene below describes (where the camera moved, how "
                 "the action progressed). It must look like a later frame of the same film, not a new illustration. ")
    if job.anchor in files and job.anchor != job.previous:
        refs += (f"Attached image {files.index(job.anchor) + 1} shows THE SAME LOCATION earlier in the video: keep its "
                 "layout, furniture, objects and colours exactly (the same bed, table, window, door, the same number "
                 "and size of everything); the camera angle and what happens may differ. ")
    return (f"Use your image generation tool to create ONE {job.orientation} image ({SIZES[job.orientation]}) and save "
            f"it to ./{job.out.name}. {refs}{job.prompt} {SIDES} No text, no letters, no labels, no watermark, no border. "
            "Do not do anything else and do not modify any other file.")


def generate(job: ImageJob, timeout: float = 900, retries: int = 1) -> float:
    """Run Codex until `job.out` exists as a valid image. Returns seconds spent; skips if the file already exists
    (unless `replace`: then the new image is drawn under a temporary name and swapped in when it is valid, so the
    old one stays visible meanwhile and stays put if Codex fails)."""
    if job.out.exists() and not job.replace:
        return 0.0
    job.out.parent.mkdir(parents=True, exist_ok=True)
    if job.replace and job.out.exists():
        draft = dataclasses.replace(job, out=job.out.with_name(f"{job.out.stem}.new.png"), replace=False)
        draft.out.unlink(missing_ok=True)
        seconds = _generate(draft, timeout, retries)
        draft.out.replace(job.out)
    else:
        seconds = _generate(job, timeout, retries)
    if job.fingerprint:
        fingerprint_path(job.out).write_text(job.fingerprint)
    if job.fix_note:
        job.fix_note.unlink(missing_ok=True)
    return seconds


def fingerprint_path(image: Path) -> Path:
    return image.with_suffix(".fp")


def _generate(job: ImageJob, timeout: float, retries: int) -> float:
    cmd = ["codex", "exec", "--skip-git-repo-check", "-s", "workspace-write", "-C", str(job.out.parent), "--json"]
    for ref in job.attachments():
        cmd += ["-i", str(ref.resolve())]
    started = time.monotonic()
    last_error = ""
    for _attempt in range(retries + 1):
        log = job.out.with_suffix(".jsonl")
        with log.open("w") as out, job.out.with_suffix(".err").open("w") as err:
            r = subprocess.run(cmd, input=_instruction(job), text=True, stdout=out, stderr=err,
                               timeout=timeout, check=False)
        if job.out.exists():
            try:
                with Image.open(job.out) as im:
                    im.verify()
                return time.monotonic() - started
            except OSError as e:
                last_error = f"invalid image: {e}"
                job.out.unlink()
        else:
            last_error = f"codex exit {r.returncode}, no {job.out.name}"
    raise RuntimeError(f"{job.out.name}: {last_error}")


def chains(jobs: list[ImageJob]) -> list[list[ImageJob]]:
    """Group jobs so a job continuing another job of the batch runs after it, in the same chain."""
    out: list[list[ImageJob]] = []
    chain_of: dict[Path, list[ImageJob]] = {}
    for job in jobs:
        chain = chain_of.get(job.previous) if job.previous else None
        if chain is None:
            chain = []
            out.append(chain)
        chain.append(job)
        chain_of[job.out] = chain
    return out


def generate_all(jobs: list[ImageJob], workers: int = 4, on_done=None, should_stop=None) -> dict[str, float | str]:
    """Generate in parallel, each job only after the jobs of this batch it depends on (the previous moment of its
    take, the first frame of its location) have finished or failed; returns {file name: seconds or error}.
    `should_stop()` cancels the images not started yet."""
    results: dict[str, float | str] = {}
    batch = {job.out for job in jobs}
    pending = list(jobs)
    cond = threading.Condition()

    def ready(job: ImageJob) -> bool:
        return all(d not in batch or d.name in results for d in job.depends_on())

    def worker() -> None:
        while True:
            with cond:
                while True:
                    if not pending:
                        return
                    job = next((j for j in pending if ready(j)), None)
                    if job is not None:
                        pending.remove(job)
                        break
                    cond.wait()
            if should_stop and should_stop():
                result: float | str = "CANCELLED"
            else:
                try:
                    result = round(generate(job), 1)
                except Exception as e:  # noqa: BLE001 - one failed image must not stop the batch
                    result = f"ERROR {e}"
            with cond:
                results[job.out.name] = result
                if on_done:
                    on_done(job, result)
                cond.notify_all()

    threads = [threading.Thread(target=worker) for _ in range(max(1, workers))]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return results
